import{z as A,x as B,o as t,c as p,q as i,j as r,D as l,d as E,s,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"无辅助损失均衡","description":"","frontmatter":{"title":"无辅助损失均衡","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aux-loss-free-balancing.md","filePath":"llm/aux-loss-free-balancing.md","lastUpdated":1791413859000}'),m={name:"llm/aux-loss-free-balancing.md"};function d(h,a,D,b,u,c){const o=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=i('<h1 id="无辅助损失均衡" tabindex="-1">无辅助损失均衡 <a class="header-anchor" href="#无辅助损失均衡" aria-label="Permalink to &quot;无辅助损失均衡&quot;">​</a></h1><div class="epigraph"><p>不把负载写进损失，而把一个随批次更新的偏置加到路由 logits 上，让过载专家下次更难被选。</p><footer>—— DeepSeek-V3 技术报告中的 auxiliary-loss-free 策略；思想亦见后续对无辅助损失均衡的专门讨论</footer></div><p><a href="/llm/soft-moe">上一课</a>用全软混合回避均衡。<a href="/llm/moe-routing">MoE 路由</a> 默认加辅助损失，与语言损失抢权：权重大了伤困惑度，小了专家崩塌。<a href="/llm/moe-load-balance">负载均衡</a> 主干课写过辅助项长什么样。本课补差：在<strong>保持稀疏 top-\\(k\\)</strong> 的前提下，用路由偏置做反馈控制，主损失不再掺均衡项。后课节点受限、序列级均衡，都默认主损失可以干净。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>辅助损失通常惩罚「专家接收分数的方差」或「实际分派与均匀的 KL」。它不区分「这个 batch 语义上就该偏某些专家」与「门崩了」。结果是路由被拉平，特化被抑制，或权重调不好时损失尖峰。缺口是把均衡从目标函数拿到<strong>控制器</strong>：观察实际负载，调 logits 偏置，语言梯度只训练专家与门的内容项。</p><p>DeepSeek-V3 采用对每个专家一个可更新的偏置 \\(b_i\\)，根据最近负载增减 \\(b_i\\)，不通过反向传播。课序把它当成方法原型，不绑定某个开源代号的全部配方。</p><p><span class="marginnote">直觉类比：\\(b_i\\) 像景区的动态票价——某处排队太长就涨价（\\(b_i\\) 减小），把边缘游客劝去次热门景点。票价只改「谁愿意去」，不改景点本身的内容；而且调价是按规则增减，不走反向传播。</span></p><p><span class="marginnote">偏置不是专家内部的 BatchNorm。它加在路由 logits 上，只改谁被选，不改专家 MLP 的激活尺度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>路由 logits \\(h_i(x)+b_i\\)，再 softmax 或 sigmoid 打分，top-\\(k\\) 与以往相同。每次（或每若干步）统计专家 \\(i\\) 的负载 \\(\\ell_i\\)（token 数或分数和）。若 \\(\\ell_i\\) 高于目标，\\(\\,b_i\\leftarrow b_i-\\gamma\\)；低于则加 \\(\\gamma\\)。\\(\\gamma\\) 是控制步长，过大振荡，过小跟不上数据分布漂移。\\(b\\) 通常不进 Adam，不当成普通参数。</p><p>可以与极小的辅助项并存做冷启动，稳定后关掉。与<a href="/llm/hash-routing">哈希路由</a> 不同，\\(h_i(x)\\) 仍可学习，特化保留；偏置只纠正系统过载。</p><h3 id="与-switch-辅助损失的对照" tabindex="-1">与 Switch 辅助损失的对照 <a class="header-anchor" href="#与-switch-辅助损失的对照" aria-label="Permalink to &quot;与 Switch 辅助损失的对照&quot;">​</a></h3><p>Switch 的辅助损失是可微的，门会主动学均匀。无辅助损失时门可以学得很尖、很特化，均匀靠 \\(b\\) 在时间上补偿。尖门加慢偏置，是「内容决定形状、反馈决定水位」。</p>',13)),(t(),r(n,null,{default:l(()=>[s(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20SW%5B%22Switch%EF%BC%9A%E8%BE%85%E5%8A%A9%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20%20%20A1%5B%22%E8%AF%AD%E8%A8%80%E6%8D%9F%E5%A4%B1%22%5D%20--%3E%20A2%5B%22%E6%80%BB%E6%8D%9F%E5%A4%B1%20%3D%20%E8%AF%AD%E8%A8%80%20%2B%20%CE%BB%C2%B7%E5%9D%87%E8%A1%A1%E9%A1%B9%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E6%A2%AF%E5%BA%A6%E6%8A%8A%E9%97%A8%E6%8B%89%E5%90%91%E5%9D%87%E5%8C%80%22%5D%0A%20%20%20%20A3%20--%3E%20A4%5B%22%E7%89%B9%E5%8C%96%E8%A2%AB%E6%8A%91%E5%88%B6%22%5D%0A%20%20end%0A%20%20subgraph%20BL%5B%22%E6%97%A0%E8%BE%85%E5%8A%A9%E6%8D%9F%E5%A4%B1%EF%BC%9A%E5%81%8F%E7%BD%AE%E6%8E%A7%E5%88%B6%22%5D%0A%20%20%20%20B1%5B%22%E8%AF%AD%E8%A8%80%E6%8D%9F%E5%A4%B1%E5%8F%AA%E8%AE%AD%E5%86%85%E5%AE%B9%22%5D%20--%3E%20B2%5B%22%E9%97%A8%E5%8F%AF%E4%BB%A5%E5%AD%A6%E5%BE%97%E5%BE%88%E5%B0%96%22%5D%0A%20%20%20%20B3%5B%22b_i%20%E6%8C%89%E8%B4%9F%E8%BD%BD%E5%A2%9E%E5%87%8F%22%5D%20--%3E%20B4%5B%22%E9%95%BF%E6%9C%9F%E6%B0%B4%E4%BD%8D%E5%9D%87%E5%8C%80%22%5D%0A%20%20end%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p><span class="marginnote">数字找找手感：DeepSeek-V3 取步长 \\(\\gamma=0.001\\)。若每步统计一次负载，一个持续过载的专家要约千步才把偏置压下 1；换成 \\(\\gamma=0.1\\)，几十步就能翻转专家排名，路由开始抖。\\(\\gamma\\) 必须和负载统计频率配套调，不是独立旋钮。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>这是离散事件的负载均衡闭环，类似排队里的动态标价。语义上热门的专家会经常过载，\\(b_i\\) 变负，把边缘 token 挤到次优专家，保护容量。分布一变，热门改名，\\(b\\) 跟着挪。因为 \\(b\\) 不反传，语言损失不会为了降低辅助项而把表示弄平——这是特化课要依赖的前提。</p><p>失败模式：\\(\\gamma\\) 与 batch 频率不匹配导致 \\(b\\) 振荡，路由在两个专家群之间抖，后课「路由抖动」会再写。控制论上要对 \\(b\\) 做动量或对 \\(\\ell_i\\) 做滑动平均。</p><p><span class="marginnote">振荡长什么样：统计太密而 \\(\\gamma\\) 偏大时，\\(b_i\\) 会走「减过头→专家变冷门→又加过头」的循环，token 在两个专家群之间反复横跳，训练曲线上表现为周期性毛刺。第一反应是调小 \\(\\gamma\\) 或对负载做滑动平均，而不是去改主损失。</span></p><p><span class="marginnote">推理时 \\(b\\) 应冻结在训练末值，或按在线负载继续调。继续调会让同一前缀在不同并发下路由不同，复现性差；冻结则遇到分布偏移会局部过载。部署要选一种并写进配置。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无辅助损失不是无均衡。没有 \\(b\\) 或容量限制，崩塌仍在。偏置解决的是平均负载，不解决单序列内部的极端不均——那是下一课之后的序列级问题。节点受限路由会再给可选集合加硬约束，偏置只在候选子集里调水位。不要把本课写成已经替代容量因子：过满仍要 drop 或溢出。</p>',8)),(t(),r(n,null,{default:l(()=>[s(o,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%86%85%E5%AE%B9%20logits%20h(x)%22%5D%20--%3E%20Sum%5B%22h%20%E5%8A%A0%E5%81%8F%E7%BD%AE%20b%22%5D%0A%20%20B%5B%22%E8%B4%9F%E8%BD%BD%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20Sum%0A%20%20Sum%20--%3E%20TopK%5B%22%E7%A8%80%E7%96%8F%20top-k%22%5D%0A%20%20TopK%20--%3E%20Load%5B%22%E7%BB%9F%E8%AE%A1%E8%B4%9F%E8%BD%BD%22%5D%0A%20%20Load%20--%3E%20B%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e("h2",{id:"小结",tabindex:"-1"},[E("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[5]||(a[5]=e("ul",null,[e("li",null,"无辅助损失均衡用路由偏置做负载闭环，主损失不再掺均匀项。"),e("li",null,"门可保持尖锐特化；偏置不进反传，只改水位。"),e("li",null,"步长失配会振荡，成为路由抖动的来源之一。"),e("li",null,"不替代容量因子与节点约束；推理要规定 \\(b\\) 冻结与否。"),e("li",null,"出处：DeepSeek-V3 技术报告中的 auxiliary-loss-free 策略。")],-1))])}const f=A(m,[["render",d]]);export{g as __pageData,f as default};
